Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>Depth z along ray
  <input type="range" id="depthZ" min="1.5" max="8" step="0.1" value="4">
</label>
<label>Relative rotation R (about vertical)
  <input type="range" id="rotY" min="-45" max="45" step="1" value="0">
</label>
<label>Relative translation T (baseline)
  <input type="range" id="transX" min="-2" max="2" step="0.05" value="0">
</label>
<button id="btnStep0">Step 1: Two-view setup</button>
<button id="btnStep1">Step 2: Depth ambiguity</button>
<button id="btnStep2">Step 3: Pose drives correspondence</button>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// ── Element specs ──────────────────────────────────────────────────────────
// target plane ℓ₂  → PlaneGeometry(1.5,1.15) + EdgesGeometry, black #111 edges, white fill opacity 0.08
// reference plane ℓ₁ → PlaneGeometry(1.5,1.15) + EdgesGeometry, black #111 edges, white fill opacity 0.08
// C₂ → SphereGeometry(0.08) black #111111
// C₁ → SphereGeometry(0.08) black #111111
// P  → SphereGeometry(0.10) red #cc1111
// p  → SphereGeometry(0.06) red #cc1111
// p' → SphereGeometry(0.06) red #cc1111
// dashed ray C₂→p→P → Line + LineDashedMaterial black
// dashed ray C₁→p'→P → Line + LineDashedMaterial black
// curved arrow p→P → TubeGeometry(QuadraticBezierCurve3) gray #999 + ConeGeometry arrowhead
// curved arrow P→p' → TubeGeometry(QuadraticBezierCurve3) gray #999 + ConeGeometry arrowhead
// self-loop at P → TubeGeometry(CatmullRomCurve3 circular arc ~270°) gray #999 + ConeGeometry arrowhead
// baseline arrow C₂→C₁ → TubeGeometry(QuadraticBezierCurve3) gray #999 + ConeGeometry arrowhead

const f = 1.5;

// Camera centers
const C2 = new THREE.Vector3(-2.0, -1.0, 0);
const C1 = new THREE.Vector3(2.0, -1.0, 0);

// Look targets (where each pinhole camera aims)
const lookT2 = new THREE.Vector3(0, 0.8, 1.5);
const lookT1 = new THREE.Vector3(0, 0.8, 1.5);

// Compute camera bases
function computeBasis(camPos, target) {
  const fwd = target.clone().sub(camPos).normalize();
  const worldUp = new THREE.Vector3(0, 1, 0);
  const right = new THREE.Vector3().crossVectors(worldUp, fwd).normalize();
  const up = new THREE.Vector3().crossVectors(fwd, right).normalize();
  return { right, up, fwd };
}

const basis2 = computeBasis(C2, lookT2);
const basis1 = computeBasis(C1, lookT1);

// Fixed image point p (in focal-length units on the target plane)
const p_img = { x: 0.25, y: 0.35 };

// ── Materials ──
const blackMat = new THREE.MeshBasicMaterial({ color: 0x111111 });
const redMat = new THREE.MeshBasicMaterial({ color: 0xcc1111 });
const grayMat = new THREE.MeshBasicMaterial({ color: 0x999999 });
const planeFillMat = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.08, side: THREE.DoubleSide });
const planeEdgeMat = new THREE.LineBasicMaterial({ color: 0x111111, linewidth: 2 });
const dashMat = new THREE.LineDashedMaterial({ color: 0x111111, dashSize: 0.18, gapSize: 0.12 });

// ── Image planes ──
function createImagePlane(basis, camPos) {
  const group = new THREE.Group();
  const geom = new THREE.PlaneGeometry(1.5, 1.15);
  const mesh = new THREE.Mesh(geom, planeFillMat);
  group.add(mesh);
  const edges = new THREE.EdgesGeometry(geom);
  const line = new THREE.LineSegments(edges, planeEdgeMat);
  group.add(line);
  const m = new THREE.Matrix4().makeBasis(basis.right, basis.up, basis.fwd);
  group.quaternion.setFromRotationMatrix(m);
  group.position.copy(camPos).add(basis.fwd.clone().multiplyScalar(f));
  scene.add(group);
  return group;
}

const plane2 = createImagePlane(basis2, C2);
const plane1 = createImagePlane(basis1, C1);

// ── Camera center spheres ──
const c2Mesh = new THREE.Mesh(new THREE.SphereGeometry(0.08, 16, 16), blackMat);
c2Mesh.position.copy(C2);
scene.add(c2Mesh);

const c1Mesh = new THREE.Mesh(new THREE.SphereGeometry(0.08, 16, 16), blackMat);
c1Mesh.position.copy(C1);
scene.add(c1Mesh);

// ── 3D point P ──
const pMesh = new THREE.Mesh(new THREE.SphereGeometry(0.10, 16, 16), redMat);
scene.add(pMesh);

// ── Image points ──
const pDot = new THREE.Mesh(new THREE.SphereGeometry(0.06, 12, 12), redMat);
scene.add(pDot);

const pPrimeDot = new THREE.Mesh(new THREE.SphereGeometry(0.06, 12, 12), redMat);
scene.add(pPrimeDot);

// ── Dashed rays ──
const ray2 = new THREE.Line(new THREE.BufferGeometry(), dashMat);
scene.add(ray2);
const ray1 = new THREE.Line(new THREE.BufferGeometry(), dashMat);
scene.add(ray1);

// ── Arrow helpers ──
function buildArrowTube(start, end, ctrl, radius) {
  const curve = new THREE.QuadraticBezierCurve3(start, ctrl, end);
  const tubeGeom = new THREE.TubeGeometry(curve, 32, radius || 0.025, 8, false);
  const tube = new THREE.Mesh(tubeGeom, grayMat);
  scene.add(tube);
  const tangent = curve.getTangent(1).normalize();
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.07, 0.18, 8), grayMat);
  cone.position.copy(end);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), tangent);
  scene.add(cone);
  return { tube, cone, curve };
}

function disposeArrow(arrow) {
  if (!arrow) return;
  scene.remove(arrow.tube);
  scene.remove(arrow.cone);
  arrow.tube.geometry.dispose();
  arrow.cone.geometry.dispose();
}

function rebuildArrow(arrowRef, start, end, ctrlOffset) {
  disposeArrow(arrowRef.obj);
  const mid = start.clone().add(end).multiplyScalar(0.5);
  const ctrl = mid.add(ctrlOffset);
  arrowRef.obj = buildArrowTube(start, end, ctrl, 0.025);
}

// Arrow containers
const arrow1Ref = { obj: null }; // p → P
const arrow2Ref = { obj: null }; // P → p'
const selfLoopRef = { obj: null }; // self-loop at P
const baselineRef = { obj: null }; // C2 → C1

// ── Self-loop builder (circular arc above P) ──
function buildSelfLoop(center) {
  const loopCenter = center.clone().add(new THREE.Vector3(0.05, 0.42, 0));
  const loopRadius = 0.32;
  const pts = [];
  const startAngle = -Math.PI * 0.75;
  const endAngle = Math.PI * 0.85;
  const steps = 40;
  for (let i = 0; i <= steps; i++) {
    const angle = startAngle + (i / steps) * (endAngle - startAngle);
    pts.push(new THREE.Vector3(
      loopCenter.x + loopRadius * Math.cos(angle),
      loopCenter.y + loopRadius * Math.sin(angle),
      loopCenter.z
    ));
  }
  const curve = new THREE.CatmullRomCurve3(pts);
  const tubeGeom = new THREE.TubeGeometry(curve, 40, 0.025, 8, false);
  const tube = new THREE.Mesh(tubeGeom, grayMat);
  scene.add(tube);
  const tangent = pts[pts.length - 1].clone().sub(pts[pts.length - 2]).normalize();
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.07, 0.18, 8), grayMat);
  cone.position.copy(pts[pts.length - 1]);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), tangent);
  scene.add(cone);
  return { tube, cone };
}

function disposeSelfLoop(obj) {
  if (!obj) return;
  scene.remove(obj.tube);
  scene.remove(obj.cone);
  obj.tube.geometry.dispose();
  obj.cone.geometry.dispose();
}

// ── Projection math ──
function backProject(pImg, z, C, basis) {
  return C.clone()
    .add(basis.right.clone().multiplyScalar(z * pImg.x / f))
    .add(basis.up.clone().multiplyScalar(z * pImg.y / f))
    .add(basis.fwd.clone().multiplyScalar(z));
}

function pointOnPlane(pImg, C, basis) {
  return C.clone()
    .add(basis.fwd.clone().multiplyScalar(f))
    .add(basis.right.clone().multiplyScalar(pImg.x))
    .add(basis.up.clone().multiplyScalar(pImg.y));
}

function toCamCoords(P_world, C, basis) {
  const rel = P_world.clone().sub(C);
  return new THREE.Vector3(rel.dot(basis.right), rel.dot(basis.up), rel.dot(basis.fwd));
}

// ── Sliders ──
const depthSlider = document.getElementById('depthZ');
const rotSlider = document.getElementById('rotY');
const transSlider = document.getElementById('transX');

// ── Update function ──
function updateScene() {
  const z = parseFloat(depthSlider.value);
  const rotYDeg = parseFloat(rotSlider.value);
  const transXVal = parseFloat(transSlider.value);
  const rotYRad = rotYDeg * Math.PI / 180;

  // Back-project p to get P in world coords
  const P_world = backProject(p_img, z, C2, basis2);

  // p on target plane (fixed)
  const p_on_plane = pointOnPlane(p_img, C2, basis2);

  // Transform P to reference camera coords with relative pose
  const P_cam2 = toCamCoords(P_world, C2, basis2);
  const cosR = Math.cos(rotYRad), sinR = Math.sin(rotYRad);
  const P_cam1 = new THREE.Vector3(
    cosR * P_cam2.x + sinR * P_cam2.z + transXVal,
    P_cam2.y,
    -sinR * P_cam2.x + cosR * P_cam2.z
  );

  // Project to get p'
  let pPrime_world = null;
  if (P_cam1.z > 0.05) {
    const pPrime_img = { x: f * P_cam1.x / P_cam1.z, y: f * P_cam1.y / P_cam1.z };
    if (Math.abs(pPrime_img.x) < 0.85 && Math.abs(pPrime_img.y) < 0.65) {
      pPrime_world = pointOnPlane(pPrime_img, C1, basis1);
    }
  }

  // Update P position
  pMesh.position.copy(P_world);

  // Update p position (fixed)
  pDot.position.copy(p_on_plane);

  // Update p' position
  if (pPrime_world) {
    pPrimeDot.visible = true;
    pPrimeDot.position.copy(pPrime_world);
  } else {
    pPrimeDot.visible = false;
  }

  // Update dashed ray from C₂ through p to P
  ray2.geometry.dispose();
  ray2.geometry = new THREE.BufferGeometry().setFromPoints([C2.clone(), p_on_plane.clone(), P_world.clone()]);
  ray2.computeLineDistances();

  // Update dashed ray from C₁ through p' to P
  if (pPrime_world) {
    ray1.visible = true;
    ray1.geometry.dispose();
    ray1.geometry = new THREE.BufferGeometry().setFromPoints([C1.clone(), pPrime_world.clone(), P_world.clone()]);
    ray1.computeLineDistances();
  } else {
    ray1.visible = false;
  }

  // Update curved arrow p→P
  const a1Start = p_on_plane.clone().add(new THREE.Vector3(0, 0.08, 0));
  const a1End = P_world.clone().add(new THREE.Vector3(-0.12, -0.12, 0));
  const a1CtrlOff = new THREE.Vector3(-0.6, 0.5, 0);
  rebuildArrow(arrow1Ref, a1Start, a1End, a1CtrlOff);

  // Update curved arrow P→p'
  if (pPrime_world) {
    const a2Start = P_world.clone().add(new THREE.Vector3(0.12, -0.12, 0));
    const a2End = pPrime_world.clone().add(new THREE.Vector3(0, 0.1, 0));
    const a2CtrlOff = new THREE.Vector3(0.6, 0.3, 0);
    rebuildArrow(arrow2Ref, a2Start, a2End, a2CtrlOff);
    arrow2Ref.obj.tube.visible = true;
    arrow2Ref.obj.cone.visible = true;
  } else {
    if (arrow2Ref.obj) {
      arrow2Ref.obj.tube.visible = false;
      arrow2Ref.obj.cone.visible = false;
    }
  }

  // Update self-loop at P
  disposeSelfLoop(selfLoopRef.obj);
  selfLoopRef.obj = buildSelfLoop(P_world);
}

// ── Baseline arrow (static) ──
const baseStart = C2.clone().add(new THREE.Vector3(0.2, -0.2, 0));
const baseEnd = C1.clone().add(new THREE.Vector3(-0.2, -0.2, 0));
const baseCtrl = new THREE.Vector3(0, -1.8, 0);
baselineRef.obj = buildArrowTube(baseStart, baseEnd, baseCtrl, 0.025);

// ── Event listeners ──
depthSlider.addEventListener('input', updateScene);
rotSlider.addEventListener('input', updateScene);
transSlider.addEventListener('input', updateScene);

// ── Demo steps ──
const steps = [
  { depthZ: 4, rotY: 0, transX: 0 },
  { depthZ: 7, rotY: 0, transX: 0 },
  { depthZ: 4, rotY: 25, transX: 1 }
];

let tweenId = null;
function goToStep(idx) {
  const target = steps[idx];
  const start = {
    depthZ: parseFloat(depthSlider.value),
    rotY: parseFloat(rotSlider.value),
    transX: parseFloat(transSlider.value)
  };
  const duration = 800;
  const t0 = performance.now();
  if (tweenId) cancelAnimationFrame(tweenId);
  function tick() {
    const t = Math.min(1, (performance.now() - t0) / duration);
    const ease = t * t * (3 - 2 * t);
    depthSlider.value = start.depthZ + (target.depthZ - start.depthZ) * ease;
    rotSlider.value = start.rotY + (target.rotY - start.rotY) * ease;
    transSlider.value = start.transX + (target.transX - start.transX) * ease;
    updateScene();
    if (t < 1) tweenId = requestAnimationFrame(tick);
  }
  tick();
}

document.getElementById('btnStep0').addEventListener('click', () => goToStep(0));
document.getElementById('btnStep1').addEventListener('click', () => goToStep(1));
document.getElementById('btnStep2').addEventListener('click', () => goToStep(2));

// ── Initial update ──
updateScene();

// ── Camera view: near-frontal to match source diagram ──
setCameraView({
  projection: 'perspective',
  azimuthDeg: 8,
  elevationDeg: 10,
  rollDeg: 0,
  heightFraction: 0.72
});

// ── Labels ──
const P_default = backProject(p_img, 4, C2, basis2);
const p_default = pointOnPlane(p_img, C2, basis2);

addLabel('ℓ<sub>2</sub>', new THREE.Vector3(-1.1, -0.3, 0.9), { fontSize: '20px', bold: true });
addLabel('ℓ<sub>1</sub>', new THREE.Vector3(1.3, -0.3, 0.9), { fontSize: '20px', bold: true });
addLabel('p', p_default.clone().add(new THREE.Vector3(-0.18, 0.12, 0)), { fontSize: '16px', bold: true });
addLabel("p'", new THREE.Vector3(1.1, 0.3, 1.2), { fontSize: '16px', bold: true });
addLabel('P', P_default.clone().add(new THREE.Vector3(-0.2, 0.15, 0)), { fontSize: '17px', bold: true });
addLabel('P=zK<sup>-1</sup>p', new THREE.Vector3(-1.2, 1.4, 1.8), { fontSize: '15px', bold: true });
addLabel("P'=MP", P_default.clone().add(new THREE.Vector3(0.5, 0.45, 0)), { fontSize: '15px', bold: true });
addLabel("p'=KP", new THREE.Vector3(1.6, 1.0, 1.5), { fontSize: '15px', bold: true });
addLabel('R, T', new THREE.Vector3(0, -1.9, 0), { fontSize: '16px', bold: true });
addLabel('Target frame', new THREE.Vector3(-2.5, -1.5, 0), { fontSize: '15px' });
addLabel('Reference frame', new THREE.Vector3(2.5, -1.5, 0), { fontSize: '15px' });

// ── Interactive elements ──
registerInteractive(pMesh, {
  title: '3D Scene Point P',
  body: 'P is the 3D point reconstructed by back-projecting the image point p using depth z and the intrinsic matrix K: P = zK⁻¹p. Both cameras observe this same point.',
  tooltip: '3D point P = zK⁻¹p'
});

registerInteractive(pDot, {
  title: 'Image point p (target frame)',
  body: 'The image point p on the target image plane ℓ₂. Back-projection through the camera center C₂ gives the ray along which P lies.',
  tooltip: 'Image point p on ℓ₂'
});

registerInteractive(pPrimeDot, {
  title: "Image point p' (reference frame)",
  body: "The projected image point p' = KP' on the reference plane ℓ₁. Its position depends on the relative pose (R, T) and the depth z.",
  tooltip: "Image point p' on ℓ₁"
});

registerInteractive(c2Mesh, {
  title: 'Target camera center C₂',
  body: 'The optical center of the target (left) camera. The back-projection ray from C₂ through p defines the line of sight to P.',
  tooltip: 'Target camera C₂'
});

registerInteractive(c1Mesh, {
  title: 'Reference camera center C₁',
  body: 'The optical center of the reference (right) camera. The projection ray from C₁ through p\' confirms the 3D location of P.',
  tooltip: 'Reference camera C₁'
});
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

systemPrompt:
You are the orchestration agent for an iterative figure-generation loop. Generation works by taking an original 2D figure, making a generation plan, generating an interactive 3D figure, and evaluating it.

You will receive the critic evaluation, including failure modes, scores, notes, and action items.
Your job is to decide which part of the system is most responsible for the problem:
- planner: the interaction plan or conceptual decomposition is wrong, incomplete, or missing the right elements
- generator: the plan is close to right, but the rendered implementation, labels, layout, interactivity, or execution is broken
- none: the figure is good enough to stop iterating

Use the failure modes and action items as the primary evidence. Do not decide from raw score thresholds alone.
Prefer planner when the critic indicates concept misunderstanding, missing core elements, wrong primitives, or the wrong overall interaction structure.
Prefer generator when the concept is right but the execution needs concrete implementation fixes like labels, wiring, geometry details, styling, or broken controls.

Return ONLY valid JSON with this exact shape:
{
	"next_step": "pass | fix_plan | refine_generation",
	"rationale": "one concise sentence explaining the decision"
}

CALIBRATION EXAMPLES — the decision turns on the failure modes, the five scores, and the notes, so only those are shown here.

